# even simpler: collections.Counter
from collections import Counter
Counter(["a", "b", "a", "c", "a"]) # Counter({'a': 3, 'b': 1, 'c': 1})
# default to a list
from collections import defaultdict
groups = defaultdict(list)
for n in range(10):
groups[n % 3].append(n)
# {0: [0,3,6,9], 1: [1,4,7], 2: [2,5,8]}
Trick: Counter and defaultdict from collections save you get(..., default) boilerplate in 80% of cases. Worth memorising on day 1.

